# Database migration with rollback support
# 20240610_add_user_preferences.sql

-- Migrate: UP
ALTER TABLE users ADD COLUMN IF NOT EXISTS preferences JSONB DEFAULT '{}';

-- Wrap new feature in try/catch for backward compatibility
-- Application code accesses preferences safely:
app.get('/api/user/preferences', async (req, res) => {
  try {
    const user = await db.users.findById(req.user.id);
    // preferences column may not exist during rolling deployment
    const prefs = user.preferences || {};
    res.json(prefs);
  } catch (err) {
    if (err.code === '42703') { // undefined_column
      logger.warn('preferences column not available yet');
      return res.json({});
    }
    throw err;
  }
});

-- Migrate: DOWN
