// Declarative Jenkinsfile
pipeline {
    agent any

    tools {
        nodejs 'node-20'
        docker 'docker-latest'
    }

    environment {
        REGISTRY = 'docker.io/myorg'
        APP_NAME = 'backend-api'
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scmGit(
                    branches: [[name: '*/main']],
                    extensions: [
                        [$class: 'CleanBeforeCheckout'],
                        [$class: 'LocalBranch', localBranch: '**']
                    ],
                    userRemoteConfigs: [[url: 'https://github.com/myorg/backend.git']]
                )
            }
        }

        stage('Test') {
            parallel {
                stage('Unit Tests') {
                    steps {
                        sh '''
                            npm ci
                            npm run test:unit
                        '''
                    }
                }
                stage('Lint & Format') {
                    steps {
                        sh '''
                            npm run lint
                            npm run format:check
                        '''
                    }
                }
                stage('Security Scan') {
                    steps {
                        sh '''
                            npm audit --audit-level=high
                            trivy fs --severity HIGH,CRITICAL .
                        '''
                    }
                }
            }
        }

        stage('Build & Package') {
            steps {
                sh '''
                    docker build -t ${REGISTRY}/${APP_NAME}:${BUILD_NUMBER} .
                    docker tag ${REGISTRY}/${APP_NAME}:${BUILD_NUMBER} ${REGISTRY}/${APP_NAME}:latest
                '''
            }
        }

        stage('Deploy to Staging') {
            steps {
                withKubeConfig([credentialsId: 'k8s-staging']) {
                    sh '''
                        kubectl set image deployment/${APP_NAME} \
                            ${APP_NAME}=${REGISTRY}/${APP_NAME}:${BUILD_NUMBER}
                    '''
                }
            }
        }
    }

    post {
        success {
            emailext(
                to: 'team@example.com',
                subject: "Pipeline Success: ${env.JOB_NAME} - ${env.BUILD_NUMBER}",
                body: "Pipeline completed successfully. See ${env.BUILD_URL}"
            )
        }
        failure {
            slackSend(
                color: 'danger',
                message: "Pipeline Failed: ${env.JOB_NAME} - ${env.BUILD_NUMBER} (${env.BUILD_URL})"
            )
        }
    }
}
